func StringToRuneSlice(s string) []rune {
	var r []rune
	for _, runeValue := range s {
		r = append(r, runeValue)
	}
	return r
}

func SortStringByCharacter(s string) string {
	r := StringToRuneSlice(s)
	sort.Slice(r, func(i, j int) bool {
		return r[i] < r[j]
	})
	return string(r)
}

func ConvertDataToSQLTest(primaryKeyList map[string][]string, dat model.AutoGenerated, isFromSource bool) (string, error) {
	configuration, err := config.LoadConfig("../../../../config.test-dipake.json")
	if err != nil {
		return "", err
	}
	sqlFile, err := ioutil.ReadFile(configuration.SQLFile)
	if err != nil {
		return "", err
	}
	sqlScript := string(sqlFile)
	// transformationList := InitTransformListNew(sqlScript, config.DDLTransform)
	sourceDb := lib.NewDatabase(configuration.SourceConfig.Host, configuration.SourceConfig.Username, configuration.SourceConfig.Password, configuration.SourceConfig.Name, configuration.SourceConfig.Port)
	// val := transformationList[fmt.Sprintf("%s.%s", dat.Payload.Source.Schema, dat.Payload.Source.Table)]
	var val config.DDLTransform
	// log.Println(transformationList)
	if isFromSource {
		transformationList := InitTransformListNew(sqlScript, configuration.DDLTransform)
		val = transformationList[fmt.Sprintf("%s.%s", dat.Payload.Source.Schema, dat.Payload.Source.Table)]
		dat = ConvertSchema(dat, val)
	} else {
		transformationList := InitTransformListDestNew(sqlScript, configuration.DDLTransform)
		// j, err := json.Marshal(transformationList["public.test_temporal"])
		// log.Println(string(j), err)

		val = transformationList[fmt.Sprintf("%s.%s", dat.Payload.Source.Schema, dat.Payload.Source.Table)]
		dat = ConvertSchemaDest(dat, val)
	}

	sql := ConvertDataToSQL(dat, primaryKeyList, val, isFromSource, sourceDb.Db)

	return sql, nil

}

